// The dependency graph: blockedBy arrows between tasks, laid out in layers (a task sits one
// layer after its latest blocker), with the critical path, the longest chain of unfinished
// work by duration, drawn in red. Landscape runs left to right, portrait top to bottom.

import { CHAR_WIDTH, esc, wrapLines } from './common'
import type { Orientation } from './common'
import { durationDays, findTask, taskIndex } from './tasknotes'
import type { Task, TaskNotesSettings } from './tasknotes'
import { linkKey } from './expr'

export type GraphNode = {
  key: string
  title: string
  task?: Task
  /** In the view (false: a blocker or dependent outside it, drawn dashed as context). */
  inView: boolean
  /** A blockedBy link that names no task. */
  missing: boolean
  level: number
  order: number
  critical: boolean
  cycle: boolean
  days: number
}

export type GraphEdge = { from: string; to: string; critical: boolean }

export type Graph = {
  nodes: GraphNode[]
  edges: GraphEdge[]
  /** View tasks with no blockedBy relation, left out of the drawing. */
  isolated: number
  /** Days of unfinished work on the critical path (0 when there is no chain). */
  criticalDays: number
  cycles: number
}

export type GraphOptions = {
  /** Leave finished tasks out altogether (their arrows go with them). */
  hideDone?: boolean
}

export function buildGraph(allViewTasks: Task[], allTasks: Task[], opts: GraphOptions = {}): Graph {
  const index = taskIndex(allTasks)
  const shown = (t: Task | undefined) => !(opts.hideDone && t?.done)
  const viewTasks = allViewTasks.filter(shown)
  const nodes = new Map<string, GraphNode>()
  const edges: GraphEdge[] = []
  const viewKeys = new Set(viewTasks.map(t => linkKey(t.file)))
  const node = (key: string, task: Task | undefined, title: string): GraphNode => {
    let n = nodes.get(key)
    if (!n) {
      n = { key, title, inView: viewKeys.has(key), missing: !task, level: 0, order: 0, critical: false, cycle: false, days: task ? durationDays(task) : 0 }
      if (task) n.task = task
      nodes.set(key, n)
    }
    return n
  }
  const addEdge = (from: string, to: string) => {
    if (from !== to && !edges.some(e => e.from === from && e.to === to)) edges.push({ from, to, critical: false })
  }
  for (const task of viewTasks) {
    const key = linkKey(task.file)
    for (const target of task.blockedBy) {
      const blocker = findTask(index, target)
      if (!shown(blocker)) continue
      const bkey = blocker ? linkKey(blocker.file) : `missing:${linkKey(target)}`
      node(key, task, task.title)
      node(bkey, blocker, blocker ? blocker.title : target)
      addEdge(bkey, key)
    }
  }
  // Dependents outside the view, one hop, as context.
  for (const task of allTasks) {
    const key = linkKey(task.file)
    if (viewKeys.has(key) || !shown(task)) continue
    for (const target of task.blockedBy) {
      const blocker = findTask(index, target)
      if (blocker && viewKeys.has(linkKey(blocker.file))) {
        node(linkKey(blocker.file), blocker, blocker.title)
        node(key, task, task.title)
        addEdge(linkKey(blocker.file), key)
      }
    }
  }

  // Layers: Kahn's order; what is left is in a cycle.
  const preds = new Map<string, string[]>()
  const succs = new Map<string, string[]>()
  for (const n of nodes.keys()) {
    preds.set(n, [])
    succs.set(n, [])
  }
  for (const e of edges) {
    preds.get(e.to)?.push(e.from)
    succs.get(e.from)?.push(e.to)
  }
  const indeg = new Map([...nodes.keys()].map(k => [k, preds.get(k)?.length ?? 0]))
  const queue = [...nodes.keys()].filter(k => indeg.get(k) === 0)
  const topo: string[] = []
  while (queue.length) {
    const k = queue.shift() as string
    topo.push(k)
    for (const s of succs.get(k) ?? []) {
      const d = (indeg.get(s) ?? 0) - 1
      indeg.set(s, d)
      if (d === 0) queue.push(s)
    }
  }
  for (const k of topo) {
    const n = nodes.get(k) as GraphNode
    n.level = Math.max(0, ...(preds.get(k) ?? []).map(p => (nodes.get(p)?.level ?? 0) + 1))
  }
  const inCycle = [...nodes.keys()].filter(k => !topo.includes(k))
  const maxLevel = Math.max(0, ...[...nodes.values()].map(n => n.level))
  for (const k of inCycle) {
    const n = nodes.get(k) as GraphNode
    n.cycle = true
    n.level = maxLevel + 1
  }

  // Critical path over unfinished work.
  const dist = new Map<string, number>()
  const via = new Map<string, string>()
  for (const k of topo) {
    const n = nodes.get(k) as GraphNode
    const own = n.task && !n.task.done ? n.days : 0
    let best = 0
    for (const p of preds.get(k) ?? []) {
      const d = dist.get(p) ?? 0
      if (d > best) {
        best = d
        via.set(k, p)
      }
    }
    dist.set(k, best + own)
  }
  let end: string | undefined
  for (const [k, d] of dist) if (end === undefined || d > (dist.get(end) ?? 0)) end = k
  let criticalDays = 0
  if (end && via.has(end)) {
    criticalDays = dist.get(end) ?? 0
    for (let k: string | undefined = end; k; k = via.get(k)) {
      const n = nodes.get(k) as GraphNode
      if (n.task?.done) break
      n.critical = true
      const p = via.get(k)
      const e = p ? edges.find(x => x.from === p && x.to === k) : undefined
      if (e && !nodes.get(p as string)?.task?.done) e.critical = true
    }
  }

  // Order within layers: barycentre sweeps to cut crossings.
  const levels = new Map<number, GraphNode[]>()
  for (const n of nodes.values()) levels.set(n.level, [...(levels.get(n.level) ?? []), n])
  for (const list of levels.values()) list.sort((a, b) => a.title.localeCompare(b.title)).forEach((n, i) => (n.order = i))
  const sorted = [...levels.keys()].sort((a, b) => a - b)
  for (let sweep = 0; sweep < 4; sweep++) {
    const pass = sweep % 2 === 0 ? sorted : [...sorted].reverse()
    for (const lv of pass) {
      const list = levels.get(lv) ?? []
      const centre = (n: GraphNode) => {
        const near = (sweep % 2 === 0 ? preds : succs).get(n.key) ?? []
        if (!near.length) return n.order
        return near.reduce((s, k) => s + (nodes.get(k)?.order ?? 0), 0) / near.length
      }
      list.sort((a, b) => centre(a) - centre(b) || a.order - b.order).forEach((n, i) => (n.order = i))
    }
  }

  const related = new Set(edges.flatMap(e => [e.from, e.to]))
  const isolated = viewTasks.filter(t => !related.has(linkKey(t.file))).length
  return { nodes: [...nodes.values()], edges, isolated, criticalDays, cycles: inCycle.length }
}

// ── drawing ──────────────────────────────────────────────────────────────

const W = 230
const H = 66
const FONT = 12
const CRITICAL = '#d62728'

/** A finished task is a dot; open work, blockers outside the view and broken links are cards. */
const DOT = 16

function isDot(n: GraphNode): boolean {
  return !!n.task?.done && !n.missing
}

function cardMarkup(n: GraphNode, x: number, y: number, settings: TaskNotesSettings): string[] {
  const parts: string[] = []
  const status = n.task?.status ?? ''
  const color = n.missing ? CRITICAL : settings.statuses.find(s => s.value.toLowerCase() === status.toLowerCase())?.color ?? '#808080'
  const done = !!n.task?.done
  const stroke = n.critical ? CRITICAL : n.missing ? CRITICAL : n.inView ? '#b8b8b8' : '#c8c8c8'
  const dash = n.inView && !n.missing ? '' : ' stroke-dasharray="5 4"'
  parts.push(`<rect x="${x}" y="${y}" width="${W}" height="${H}" rx="7" fill="${n.inView ? '#ffffff' : '#f6f6f6'}" stroke="${stroke}" stroke-width="${n.critical ? 2.5 : 1.2}"${dash}/>`)
  parts.push(`<rect x="${x}" y="${y}" width="6" height="${H}" rx="3" fill="${esc(color)}"/>`)
  const maxChars = Math.floor((W - 22) / (FONT * CHAR_WIDTH))
  const lines = wrapLines(n.missing ? `not found: ${n.title}` : n.title, maxChars)
  const shown = lines.slice(0, 2)
  if (lines.length > 2) shown[1] = `${(shown[1] ?? '').slice(0, Math.max(0, maxChars - 1))}…`
  shown.forEach((line, i) => {
    parts.push(`<text x="${x + 14}" y="${y + 19 + i * 15}" font-size="${FONT}" fill="#1f1f1f"${done ? ' text-decoration="line-through"' : ''}>${esc(line)}</text>`)
  })
  const meta = n.missing
    ? 'blockedBy link with no task'
    : [n.task?.statusDef?.label ?? status, n.task?.size, n.task && !done ? `${Math.round(n.days * 10) / 10}d` : '', n.inView ? '' : 'outside view', n.cycle ? 'in a cycle' : '']
        .filter(Boolean)
        .join(' · ')
  parts.push(`<text x="${x + 14}" y="${y + H - 10}" font-size="10" fill="${n.cycle ? CRITICAL : '#666666'}">${esc(meta)}</text>`)
  return parts
}

/**
 * The graph as SVG. Layers run left to right (landscape) or top to bottom (portrait); each
 * layer is as deep as its biggest node, so a layer of finished dots takes little room.
 * The pane draws it as a picture: a finished task is a plain dot (its title is in the
 * task list the pane shows under the graph, where hover and presses work).
 */
export function graphSvg(graph: Graph, settings: TaskNotesSettings, orientation: Orientation): string {
  const landscape = orientation === 'landscape'
  const pad = 20
  const size = (n: GraphNode) => (isDot(n) ? { w: DOT, h: DOT } : { w: W, h: H })
  const layerGap = landscape ? 80 : 56
  const siblingGap = (a: GraphNode, b: GraphNode) => (isDot(a) && isDot(b) ? 10 : 22)

  const levels = [...new Set(graph.nodes.map(n => n.level))].sort((a, b) => a - b)
  const pos = new Map<string, { x: number; y: number; w: number; h: number }>()
  let along = pad
  for (const lv of levels) {
    const layer = graph.nodes.filter(n => n.level === lv).sort((a, b) => a.order - b.order)
    const depth = Math.max(...layer.map(n => (landscape ? size(n).w : size(n).h)))
    let across = pad
    layer.forEach((n, i) => {
      const s = size(n)
      if (i > 0) across += siblingGap(layer[i - 1] as GraphNode, n)
      // Centre a dot in its layer's depth, so arrows into it stay level.
      const offset = (depth - (landscape ? s.w : s.h)) / 2
      pos.set(n.key, landscape ? { x: along + offset, y: across, ...s } : { x: across, y: along + offset, ...s })
      across += landscape ? s.h : s.w
    })
    along += depth + layerGap
  }
  const extent = [...pos.values()]
  const width = Math.max(W + 2 * pad, ...extent.map(p => p.x + p.w + pad))
  const height = Math.max(H + 2 * pad, ...extent.map(p => p.y + p.h + pad))
  const parts: string[] = [
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" font-family="Segoe UI, Helvetica, Arial, sans-serif">`,
    '<defs>',
    '<marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="#888"/></marker>',
    `<marker id="arrow-critical" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="${CRITICAL}"/></marker>`,
    '</defs>',
    `<rect x="0" y="0" width="${width}" height="${height}" fill="#ffffff"/>`,
  ]
  const order = [...graph.edges].sort((a, b) => Number(a.critical) - Number(b.critical))
  for (const e of order) {
    const from = pos.get(e.from)
    const to = pos.get(e.to)
    if (!from || !to) continue
    const [x1, y1, x2, y2] = landscape
      ? [from.x + from.w, from.y + from.h / 2, to.x, to.y + to.h / 2]
      : [from.x + from.w / 2, from.y + from.h, to.x + to.w / 2, to.y]
    const bend = landscape ? Math.max(30, (x2 - x1) / 2) : Math.max(24, (y2 - y1) / 2)
    const d = landscape
      ? `M${x1},${y1} C${x1 + bend},${y1} ${x2 - bend},${y2} ${x2},${y2}`
      : `M${x1},${y1} C${x1},${y1 + bend} ${x2},${y2 - bend} ${x2},${y2}`
    const fromDone = graph.nodes.find(n => n.key === e.from)?.task?.done
    const color = e.critical ? CRITICAL : fromDone ? '#c4c4c4' : '#9a9a9a'
    parts.push(`<path d="${d}" fill="none" stroke="${color}" stroke-width="${e.critical ? 2.5 : 1.4}" marker-end="url(#${e.critical ? 'arrow-critical' : 'arrow'})"/>`)
  }
  for (const n of graph.nodes.filter(m => !isDot(m))) {
    const p = pos.get(n.key)
    if (p) parts.push('<g>', ...cardMarkup(n, p.x, p.y, settings), '</g>')
  }
  for (const n of graph.nodes.filter(isDot)) {
    const p = pos.get(n.key)
    if (!p) continue
    const color = n.task?.statusDef?.color ?? '#00aa00'
    parts.push(
      '<g class="dot">',
      `<title>${esc(`${n.title} · ${n.task?.statusDef?.label ?? n.task?.status ?? 'done'}`)}</title>`,
      `<circle cx="${p.x + DOT / 2}" cy="${p.y + DOT / 2}" r="${DOT / 2 - 1}" fill="${esc(color)}" stroke="#ffffff" stroke-width="2"/>`,
      '</g>',
    )
  }
  parts.push('</svg>')
  return parts.join('')
}

files.hooks/model.ts:
// What a pane shows for one view of a base: its rows as TaskNotes tasks, grouped into board
// columns or list sections, each card with the properties the view's `order` names.
// Pure: register.tsx loads the files and draws what this returns.

import type { Layout } from '../types'
import { displayName, evaluateView, groupRows } from './bases'
import type { BaseConfig, BaseView, EvalContext, Row } from './bases'
import { FileV, formatDate, toText } from './expr'
import { findTask, fieldKey, priorityOrder, statusLabel, statusOrder, taskIndex } from './tasknotes'
import type { Task, TaskNotesSettings } from './tasknotes'

export type MetaItem = { text: string; color?: string }

export type Card = {
  key: string
  path: string
  title: string
  status: string
  color?: string
  done: boolean
  meta: MetaItem[]
}

export type Column = { key: string; label: string; color?: string; cards: Card[] }

export type Model = {
  view: BaseView
  /** The layout the view's own type asks for. */
  natural: Exclude<Layout, 'graph'>
  matched: number
  shown: number
  warnings: string[]
  rows: Row[]
  /** The rows' tasks, in the view's sort order. */
  tasks: Task[]
}

// ── pill filters ─────────────────────────────────────────────────────────

export type Filters = { projects: string[]; contexts: string[] }
export type Facet = { name: string; count: number }

const lower = (s: string) => s.toLowerCase()

/**
 * The view narrowed by the pills: a task stays when it is in one of the selected projects
 * (if any are selected) and has one of the selected contexts (if any are selected).
 */
export function narrow(model: Model, filters: Filters): Model {
  const projects = filters.projects.map(lower)
  const contexts = filters.contexts.map(lower)
  if (!projects.length && !contexts.length) return model
  const keep = model.tasks.map(t =>
    (!projects.length || t.projects.some(p => projects.includes(lower(p)))) &&
    (!contexts.length || t.contexts.some(c => contexts.includes(lower(c.replace(/^@/, ''))))),
  )
  const rows = model.rows.filter((_, k) => keep[k])
  return { ...model, rows, tasks: model.tasks.filter((_, k) => keep[k]), matched: rows.length, shown: rows.length }
}

/** The projects and contexts of a view's tasks, most used first: what the pills offer. */
export function facets(tasks: Task[]): { projects: Facet[]; contexts: Facet[] } {
  const count = (names: string[][]) => {
    const seen = new Map<string, Facet>()
    for (const list of names) {
      for (const name of new Set(list)) {
        const f = seen.get(lower(name))
        if (f) f.count++
        else seen.set(lower(name), { name, count: 1 })
      }
    }
    return [...seen.values()].sort((a, b) => b.count - a.count || a.name.localeCompare(b.name))
  }
  return {
    projects: count(tasks.map(t => t.projects)),
    contexts: count(tasks.map(t => t.contexts.map(c => c.replace(/^@/, '')))),
  }
}

export function naturalLayout(type: string): Exclude<Layout, 'graph'> {
  const t = type.toLowerCase()
  if (t.includes('kanban') || t === 'board') return 'board'
  if (t.includes('calendar') || t.includes('agenda')) return 'agenda'
  return 'list'
}

export type ModelInput = {
  config: BaseConfig
  view: BaseView
  files: FileV[]
  taskOf: (file: FileV) => Task
  ctx: EvalContext
}

export function buildModel({ config, view, files, taskOf, ctx }: ModelInput): Model {
  const result = evaluateView(config, view, files, ctx)
  return {
    view,
    natural: naturalLayout(view.type),
    matched: result.matched,
    shown: result.rows.length,
    warnings: result.warnings,
    rows: result.rows,
    tasks: result.rows.map(r => taskOf(r.file)),
  }
}

function isProp(prop: string, settings: TaskNotesSettings, field: string): boolean {
  const key = fieldKey(settings, field)
  return prop === key || prop === `note.${key}`
}

function shortDate(ms: number, now: number): string {
  const sameYear = new Date(ms).getFullYear() === new Date(now).getFullYear()
  return formatDate(ms, sameYear ? 'ddd D MMM' : 'D MMM YYYY')
}

function startOfDay(ms: number): number {
  const d = new Date(ms)
  return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()
}

const SKIP = new Set(['file.name', 'file.basename', 'title', 'note.title', 'file.tags', 'tags', 'note.tags', 'complete_instances', 'note.complete_instances'])

/**
 * A card: the title, then the view's `order` properties TaskNotes knows how to show
 * (status, priority, due, …), then Done When progress. `extras` adds the other properties
 * the view lists (formulas, custom fields) as `name: value`, as a table view shows them.
 */
export function cardOf(
  row: Row,
  task: Task,
  config: BaseConfig,
  settings: TaskNotesSettings,
  index: Map<string, Task>,
  now: number,
  opts: { order: string[]; groupProp?: string; extras?: boolean },
): Card {
  const meta: MetaItem[] = []
  const props = [...new Set(opts.order.length ? opts.order : DEFAULT_ORDER)]
  const today = startOfDay(now)
  for (const prop of props) {
    if (SKIP.has(prop) || prop === opts.groupProp) continue
    if (isProp(prop, settings, 'status')) {
      meta.push({ text: task.statusDef?.label ?? task.status, ...(task.statusDef ? { color: task.statusDef.color } : {}) })
    } else if (isProp(prop, settings, 'priority')) {
      if (task.priority !== 'none') meta.push({ text: `${task.priorityDef?.label ?? task.priority} priority`, ...(task.priorityDef ? { color: task.priorityDef.color } : {}) })
    } else if (isProp(prop, settings, 'due')) {
      if (task.due) {
        const late = !task.done && startOfDay(task.due.ms) < today
        meta.push({ text: `due ${shortDate(task.due.ms, now)}${late ? ' (overdue)' : ''}`, ...(late ? { color: '#d62728' } : {}) })
      }
    } else if (isProp(prop, settings, 'scheduled')) {
      if (task.scheduled) meta.push({ text: `scheduled ${shortDate(task.scheduled.ms, now)}` })
    } else if (isProp(prop, settings, 'projects')) {
      if (task.projects.length) meta.push({ text: `▸ ${task.projects.join(', ')}` })
    } else if (isProp(prop, settings, 'contexts')) {
      if (task.contexts.length) meta.push({ text: task.contexts.map(c => `@${c.replace(/^@/, '')}`).join(' ') })
    } else if (isProp(prop, settings, 'blockedBy')) {
      const open = task.blockedBy.filter(t => !findTask(index, t)?.done)
      if (open.length) meta.push({ text: `⛔ blocked by ${open.length}`, color: '#d62728' })
    } else if (isProp(prop, settings, 'recurrence')) {
      if (task.recurrence) meta.push({ text: `↻ ${recurrenceWord(task.recurrence)}` })
    } else if (prop === 'assignee' || prop === 'note.assignee') {
      if (task.assignee.length) meta.push({ text: `→ ${task.assignee.join(', ')}` })
    } else if (prop === 'size' || prop === 'note.size') {
      if (task.size) meta.push({ text: `size ${task.size}` })
    } else if (opts.extras) {
      const text = toText(row.get(prop))
      if (text) meta.push({ text: `${displayName(config, prop)}: ${text}` })
    }
  }
  if (task.doneWhen) meta.push({ text: `done when ${task.doneWhen.done}/${task.doneWhen.total}`, ...(task.doneWhen.done === task.doneWhen.total ? { color: '#00aa00' } : {}) })
  const card: Card = { key: task.file.path, path: task.file.path, title: task.title, status: task.status, done: task.done, meta }
  if (task.statusDef) card.color = task.statusDef.color
  return card
}

/**
 * Everything a task has, one line each, whatever the view lists: what the hover popup of a
 * card shows. Properties a task lacks leave no line.
 */
export function detailOf(task: Task, index: Map<string, Task>, now: number): MetaItem[] {
  const out: MetaItem[] = []
  const today = startOfDay(now)
  out.push({ text: `Status: ${task.statusDef?.label ?? task.status}`, ...(task.statusDef ? { color: task.statusDef.color } : {}) })
  if (task.priority !== 'none') out.push({ text: `Priority: ${task.priorityDef?.label ?? task.priority}`, ...(task.priorityDef ? { color: task.priorityDef.color } : {}) })
  if (task.due) {
    const late = !task.done && startOfDay(task.due.ms) < today
    out.push({ text: `Due: ${shortDate(task.due.ms, now)}${late ? ' (overdue)' : ''}`, ...(late ? { color: '#d62728' } : {}) })
  }
  if (task.scheduled) out.push({ text: `Scheduled: ${shortDate(task.scheduled.ms, now)}` })
  if (task.completed) out.push({ text: `Completed: ${shortDate(task.completed.ms, now)}` })
  if (task.recurrence) out.push({ text: `Repeats: ${recurrenceWord(task.recurrence)}` })
  if (task.projects.length) out.push({ text: `Projects: ${task.projects.join(', ')}` })
  if (task.contexts.length) out.push({ text: `Contexts: ${task.contexts.map(c => `@${c.replace(/^@/, '')}`).join(' ')}` })
  if (task.assignee.length) out.push({ text: `Assignee: ${task.assignee.join(', ')}` })
  if (task.size) out.push({ text: `Size: ${task.size}` })
  if (task.estimateMinutes) out.push({ text: `Estimate: ${task.estimateMinutes} min` })
  const open = task.blockedBy.filter(t => !findTask(index, t)?.done)
  if (open.length) out.push({ text: `Blocked by: ${open.map(t => findTask(index, t)?.title ?? t).join(', ')}`, color: '#d62728' })
  if (task.awaiting) out.push({ text: `Awaiting: ${task.awaiting}` })
  if (task.doneWhen) out.push({ text: `Done when: ${task.doneWhen.done}/${task.doneWhen.total}`, ...(task.doneWhen.done === task.doneWhen.total ? { color: '#00aa00' } : {}) })
  if (task.readyWhen) out.push({ text: `Ready when: ${task.readyWhen.done}/${task.readyWhen.total}` })
  if (task.file.tags.length) out.push({ text: task.file.tags.map(t => (t.startsWith('#') ? t : `#${t}`)).join(' ') })
  out.push({ text: task.file.path })
  return out
}

/** Card properties when a view lists none: TaskNotes' usual ones. */
const DEFAULT_ORDER = ['status', 'priority', 'due', 'scheduled', 'projects', 'contexts', 'blockedBy', 'recurrence']

/** Cards for the rows of `model`, with the view's own property order. */
export function cardsOf(model: Model, config: BaseConfig, settings: TaskNotesSettings, allTasks: Task[], now: number, groupProp?: string): Card[] {
  const index = taskIndex(allTasks)
  const extras = model.view.type.toLowerCase().includes('table')
  return model.rows.map((row, k) =>
    cardOf(row, model.tasks[k] as Task, config, settings, index, now, { order: model.view.order, extras, ...(groupProp ? { groupProp } : {}) }),
  )
}

function recurrenceWord(rule: string): string {
  const freq = /FREQ=(\w+)/i.exec(rule)?.[1] ?? /\b(daily|weekly|monthly|yearly)\b/i.exec(rule)?.[1] ?? 'recurring'
  const interval = Number(/INTERVAL=(\d+)/i.exec(rule)?.[1] ?? 1)
  const word = freq.toLowerCase()
  if (interval <= 1) return word
  const unit = { daily: 'days', weekly: 'weeks', monthly: 'months', yearly: 'years' }[word] ?? word
  return `every ${interval} ${unit}`
}

/**
 * Columns (board) or sections (list). The board groups by the view's groupBy, else status;
 * status columns follow TaskNotes' order and include empty ones unless the view hides them.
 * A list without groupBy is one section.
 */
export function columnsOf(
  model: Model,
  config: BaseConfig,
  settings: TaskNotesSettings,
  allTasks: Task[],
  now: number,
  layout: 'board' | 'list',
): Column[] {
  const spec = model.view.groupBy ?? (layout === 'board' ? { property: fieldKey(settings, 'status'), direction: 'ASC' as const } : undefined)
  if (!spec) {
    return [{ key: 'all', label: model.view.name, cards: cardsOf(model, config, settings, allTasks, now) }]
  }
  const byStatus = isProp(spec.property, settings, 'status')
  const byPriority = isProp(spec.property, settings, 'priority')
  const cards = cardsOf(model, config, settings, allTasks, now, spec.property)
  const cardByRow = new Map(model.rows.map((r, k) => [r, cards[k] as Card]))
  const groups = groupRows(model.rows, spec, keys => {
    if (byStatus) return statusOrder(settings, keys)
    if (byPriority) return priorityOrder(settings, keys)
    return undefined
  })
  const columns: Column[] = groups.map(g => {
    const col: Column = { key: g.key, label: byStatus ? statusLabel(settings, g.label) : g.label, cards: g.rows.map(r => cardByRow.get(r) as Card) }
    const color = byStatus ? settings.statuses.find(s => s.value.toLowerCase() === g.key)?.color : byPriority ? settings.priorities.find(p => p.value.toLowerCase() === g.key)?.color : undefined
    if (color) col.color = color
    return col
  })
  if (layout === 'board' && byStatus && model.view.options.hideEmptyColumns !== true) {
    for (const s of settings.statuses) {
      if (!columns.some(c => c.key === s.value.toLowerCase())) columns.push({ key: s.value.toLowerCase(), label: s.label, color: s.color, cards: [] })
    }
    const ordered = statusOrder(settings, columns.map(c => c.key))
    columns.sort((a, b) => ordered.indexOf(a.key) - ordered.indexOf(b.key))
    if (spec.direction === 'DESC') columns.reverse()
  }
  return columns
}

files.hooks/tasknotes.ts:
// TaskNotes: its settings (data.json) and a task as the panes draw it. Field names go
// through TaskNotes' field mapping, so a vault that renamed `due` to `deadline` still works.
// The field normalisation follows bob-workspace's task-notes.ts (same author, MIT).

import { DateV, FileV, LinkV, linkKey, toDate, toText, wrap } from './expr'
import { isRecord } from './yaml'

export type StatusDef = { value: string; label: string; color: string; isCompleted: boolean; order: number }
export type PriorityDef = { value: string; label: string; color: string; weight: number }

export type TaskNotesSettings = {
  /** False when the vault has no TaskNotes data.json (defaults are used). */
  found: boolean
  tasksFolder: string
  archiveFolder: string
  excludedFolders: string[]
  identify: { method: 'property' | 'tag'; property: string; value: string; tag: string }
  statuses: StatusDef[]
  priorities: PriorityDef[]
  fieldMapping: Record<string, string>
  /** TaskNotes command id (`open-kanban-view`, …) → the .base file it opens. */
  viewFiles: Record<string, string>
}

const DEFAULT_STATUSES: StatusDef[] = [
  { value: 'open', label: 'Open', color: '#808080', isCompleted: false, order: 1 },
  { value: 'in-progress', label: 'In progress', color: '#0066cc', isCompleted: false, order: 2 },
  { value: 'done', label: 'Done', color: '#00aa00', isCompleted: true, order: 3 },
]

const DEFAULT_PRIORITIES: PriorityDef[] = [
  { value: 'low', label: 'Low', color: '#00aa00', weight: 1 },
  { value: 'normal', label: 'Normal', color: '#ffaa00', weight: 2 },
  { value: 'high', label: 'High', color: '#ff0000', weight: 3 },
]

const DEFAULT_VIEW_FILES: Record<string, string> = {
  'open-kanban-view': 'TaskNotes/Views/kanban-default.base',
  'open-tasks-view': 'TaskNotes/Views/tasks-default.base',
  'open-agenda-view': 'TaskNotes/Views/agenda-default.base',
  'open-advanced-calendar-view': 'TaskNotes/Views/calendar-default.base',
  'open-calendar-view': 'TaskNotes/Views/mini-calendar-default.base',
  relationships: 'TaskNotes/Views/relationships.base',
}

/** Short names for `/taskboard <name>`, each a TaskNotes command whose base file it opens. */
export const VIEW_ALIASES: Record<string, string> = {
  kanban: 'open-kanban-view',
  board: 'open-kanban-view',
  tasks: 'open-tasks-view',
  list: 'open-tasks-view',
  agenda: 'open-agenda-view',
  calendar: 'open-advanced-calendar-view',
  'mini-calendar': 'open-calendar-view',
  relationships: 'relationships',
}

const str = (v: unknown, fallback: string) => (typeof v === 'string' && v.trim() ? v.trim() : fallback)

export function parseSettings(json: string | undefined): TaskNotesSettings {
  let data: Record<string, unknown> = {}
  let found = false
  if (json) {
    try {
      const parsed: unknown = JSON.parse(json)
      if (isRecord(parsed)) {
        data = parsed
        found = true
      }
    } catch {
      // A broken data.json reads as defaults.
    }
  }
  const statuses = Array.isArray(data.customStatuses)
    ? data.customStatuses.filter(isRecord).map((s, k) => ({
        value: str(s.value, `status-${k}`),
        label: str(s.label, str(s.value, `Status ${k}`)),
        color: str(s.color, '#808080'),
        isCompleted: s.isCompleted === true,
        order: typeof s.order === 'number' ? s.order : k,
      }))
    : DEFAULT_STATUSES
  const priorities = Array.isArray(data.customPriorities)
    ? data.customPriorities.filter(isRecord).map((p, k) => ({
        value: str(p.value, `priority-${k}`),
        label: str(p.label, str(p.value, `Priority ${k}`)),
        color: str(p.color, '#808080'),
        weight: typeof p.weight === 'number' ? p.weight : k,
      }))
    : DEFAULT_PRIORITIES
  const fieldMapping: Record<string, string> = {}
  if (isRecord(data.fieldMapping)) {
    for (const [k, v] of Object.entries(data.fieldMapping)) if (typeof v === 'string' && v) fieldMapping[k] = v
  }
  const viewFiles: Record<string, string> = { ...DEFAULT_VIEW_FILES }
  if (isRecord(data.commandFileMapping)) {
    for (const [k, v] of Object.entries(data.commandFileMapping)) if (typeof v === 'string' && v) viewFiles[k] = v
  }
  const excluded = data.excludedFolders
  return {
    found,
    tasksFolder: str(data.tasksFolder, 'TaskNotes/Tasks').replace(/\/+$/, ''),
    archiveFolder: str(data.archiveFolder, 'TaskNotes/Archive').replace(/\/+$/, ''),
    excludedFolders: (Array.isArray(excluded) ? excluded.map(String) : typeof excluded === 'string' ? excluded.split(',') : [])
      .map(s => s.trim().replace(/\/+$/, ''))
      .filter(Boolean),
    identify: {
      method: data.taskIdentificationMethod === 'property' ? 'property' : 'tag',
      property: str(data.taskPropertyName, 'type'),
      value: str(data.taskPropertyValue, 'task'),
      tag: str(data.taskTag, 'task').replace(/^#/, ''),
    },
    statuses: [...statuses].sort((a, b) => a.order - b.order),
    priorities: [...priorities].sort((a, b) => b.weight - a.weight),
    fieldMapping,
    viewFiles,
  }
}

/** The frontmatter key TaskNotes stores a field under. */
export function fieldKey(settings: TaskNotesSettings, field: string): string {
  return settings.fieldMapping[field] ?? field
}

export function isTaskFile(file: FileV, settings: TaskNotesSettings): boolean {
  if (settings.excludedFolders.some(f => file.path.toLowerCase().startsWith(`${f.toLowerCase()}/`))) return false
  const { method, property, value, tag } = settings.identify
  if (method === 'tag') return file.tags.some(t => t.toLowerCase() === tag.toLowerCase() || t.toLowerCase().startsWith(`${tag.toLowerCase()}/`))
  const raw = file.properties[property]
  const values = Array.isArray(raw) ? raw : [raw]
  return values.some(v => typeof v === 'string' && v.toLowerCase() === value.toLowerCase())
}

// ── a task ───────────────────────────────────────────────────────────────

export type Progress = { done: number; total: number }

export type Task = {
  file: FileV
  title: string
  status: string
  statusDef?: StatusDef
  done: boolean
  priority: string
  priorityDef?: PriorityDef
  due: DateV | null
  scheduled: DateV | null
  completed: DateV | null
  projects: string[]
  contexts: string[]
  /** Link targets of the tasks this one waits for. */
  blockedBy: string[]
  recurrence?: string
  completeInstances: string[]
  size?: string
  estimateMinutes?: number
  assignee: string[]
  /** `## Done When` checkboxes; `## Ready When` ones. */
  doneWhen?: Progress
  readyWhen?: Progress
  awaiting?: string
}

function list(v: unknown): unknown[] {
  if (v === null || v === undefined || v === '') return []
  if (Array.isArray(v)) return v
  if (typeof v === 'string' && v.includes(',') && !v.includes('[[')) return v.split(',').map(s => s.trim()).filter(Boolean)
  return [v]
}

function names(v: unknown): string[] {
  return list(v)
    .map(item => {
      const w = wrap(item)
      return w instanceof LinkV ? w.display || w.target : toText(w)
    })
    .filter(Boolean)
}

/** A blockedBy entry is a wikilink, or `{ uid: wikilink, reltype }`. */
export function blockerTargets(v: unknown): string[] {
  return list(v)
    .map(item => {
      const raw = isRecord(item) ? item.uid : item
      const w = wrap(raw)
      return w instanceof LinkV ? w.target : typeof w === 'string' ? w : ''
    })
    .filter(Boolean)
}

/** Checkbox counts under the first heading named like one of `titles`. */
export function sectionProgress(body: string, titles: string[]): Progress | undefined {
  const lines = body.split(/\r?\n/)
  const want = titles.map(t => t.toLowerCase())
  let level = 0
  let inSection = false
  let done = 0
  let total = 0
  let fence = false
  for (const line of lines) {
    if (/^\s*(```|~~~)/.test(line)) fence = !fence
    if (fence) continue
    const h = /^(#{1,6})\s+(.*?)\s*#*\s*$/.exec(line)
    if (h) {
      const depth = (h[1] ?? '').length
      if (inSection && depth <= level) break
      if (!inSection && want.includes((h[2] ?? '').toLowerCase())) {
        inSection = true
        level = depth
      }
      continue
    }
    if (!inSection) continue
    const box = /^\s*[-*+]\s+\[(.)\]/.exec(line)
    if (box) {
      total++
      if ((box[1] ?? ' ') !== ' ') done++
    }
  }
  return inSection && total > 0 ? { done, total } : undefined
}

export function toTask(file: FileV, body: string, settings: TaskNotesSettings): Task {
  const p = file.properties
  const get = (field: string) => p[fieldKey(settings, field)]
  const status = toText(wrap(get('status'))).trim() || 'none'
  const priority = toText(wrap(get('priority'))).trim() || 'none'
  const statusDef = settings.statuses.find(s => s.value.toLowerCase() === status.toLowerCase())
  const priorityDef = settings.priorities.find(s => s.value.toLowerCase() === priority.toLowerCase())
  const title = toText(wrap(get('title'))).trim() || file.basename
  const estimate = Number(get('timeEstimate'))
  const task: Task = {
    file,
    title,
    status,
    done: statusDef ? statusDef.isCompleted : /^(done|completed|cancel+ed|archived)$/i.test(status),
    priority,
    due: toDate(get('due')),
    scheduled: toDate(get('scheduled')),
    completed: toDate(get('completedDate')),
    projects: names(get('projects')),
    contexts: names(get('contexts')),
    blockedBy: blockerTargets(get('blockedBy')),
    completeInstances: list(get('completeInstances')).map(v => toText(wrap(v))).filter(Boolean),
    assignee: names(p.assignee),
  }
  if (statusDef) task.statusDef = statusDef
  if (priorityDef) task.priorityDef = priorityDef
  const recurrence = toText(wrap(get('recurrence'))).trim()
  if (recurrence) task.recurrence = recurrence
  const size = toText(wrap(p.size)).trim()
  if (size) task.size = size
  if (Number.isFinite(estimate) && estimate > 0) task.estimateMinutes = estimate
  const doneWhen = sectionProgress(body, ['Done When', 'Acceptance Criteria'])
  if (doneWhen) task.doneWhen = doneWhen
  const readyWhen = sectionProgress(body, ['Ready When'])
  if (readyWhen) task.readyWhen = readyWhen
  const awaiting = toText(wrap(p.awaiting)).trim()
  if (awaiting) task.awaiting = awaiting
  return task
}

export function statusLabel(settings: TaskNotesSettings, value: string): string {
  return settings.statuses.find(s => s.value.toLowerCase() === value.toLowerCase())?.label ?? value
}

export function statusColor(settings: TaskNotesSettings, value: string): string | undefined {
  return settings.statuses.find(s => s.value.toLowerCase() === value.toLowerCase())?.color
}

/** Group keys in TaskNotes' status order (unknown values after them). */
export function statusOrder(settings: TaskNotesSettings, keys: string[]): string[] {
  const rank = (k: string) => {
    const i = settings.statuses.findIndex(s => s.value.toLowerCase() === k)
    return i < 0 ? settings.statuses.length : i
  }
  return [...keys].sort((a, b) => rank(a) - rank(b))
}

/** Group keys by priority weight, highest first. */
export function priorityOrder(settings: TaskNotesSettings, keys: string[]): string[] {
  const weight = (k: string) => settings.priorities.find(p => p.value.toLowerCase() === k)?.weight ?? -1
  return [...keys].sort((a, b) => weight(b) - weight(a))
}

const SIZE_DAYS: Record<string, number> = { xs: 0.5, s: 1, m: 2, l: 4, xl: 8 }

/** A task's duration in days for the critical path: timeEstimate (minutes, 8h days), else size, else 1. */
export function durationDays(task: Task): number {
  if (task.estimateMinutes) return task.estimateMinutes / 480
  const bySize = task.size ? SIZE_DAYS[task.size.toLowerCase()] : undefined
  return bySize ?? 1
}

/** Index tasks by link identity (note name), for resolving blockedBy. */
export function taskIndex(tasks: Task[]): Map<string, Task> {
  const index = new Map<string, Task>()
  for (const t of tasks) {
    index.set(linkKey(t.file), t)
    index.set(t.file.path.replace(/\.md$/i, '').toLowerCase(), t)
  }
  return index
}

export function findTask(index: Map<string, Task>, target: string): Task | undefined {
  const clean = target.replace(/\\/g, '/').replace(/\.md$/i, '').toLowerCase()
  return index.get(clean) ?? index.get(linkKey(target))
}

files.hooks/yaml.ts:
// A small YAML reader for note frontmatter and Obsidian `.base` files. A plugin has no npm
// packages, so this covers the subset Obsidian and TaskNotes write: block mappings and
// sequences (a sequence may sit at its key's own indent), sequences of mappings, flow
// `[...]` / `{...}`, plain, single- and double-quoted scalars (over several lines too),
// block scalars (`|`, `>`, with `-`/`+`), and comments. Dates stay strings: Bases converts
// them with `date()`, as Obsidian does.

type Line = { indent: number; text: string }

export class YamlError extends Error {}

export function parseYaml(src: string): unknown {
  const lines: (Line | undefined)[] = src.replace(/\r/g, '').split('\n').map(raw => {
    const text = raw.replace(/\t/g, '  ')
    const trimmed = text.trimStart()
    return { indent: text.length - trimmed.length, text: trimmed.trimEnd() }
  })
  const p = new Parser(lines)
  return p.document()
}

/** Split a markdown note into its frontmatter object and body. */
export function splitFrontmatter(text: string): { data: Record<string, unknown>; body: string; error?: string } {
  const m = /^---[ \t]*\r?\n([\s\S]*?)\r?\n(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/.exec(text)
  if (!m) return { data: {}, body: text }
  const body = text.slice(m[0].length)
  try {
    const parsed = parseYaml(m[1] ?? '')
    return { data: isRecord(parsed) ? parsed : {}, body }
  } catch (err) {
    return { data: {}, body, error: err instanceof Error ? err.message : String(err) }
  }
}

export function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v)
}

const KEY = /^(?:"((?:[^"\\]|\\.)*)"|'((?:[^']|'')*)'|([^\s'"#[\]{},&*!|>%@`-][^:]*?|-[^\s:][^:]*?))[ \t]*:(?:[ \t]+(.*)|$)/

function isSeqItem(text: string): boolean {
  return text === '-' || text.startsWith('- ')
}

function isBlank(line: Line | undefined): boolean {
  return !line || line.text === '' || line.text.startsWith('#')
}

class Parser {
  i = 0
  constructor(private lines: (Line | undefined)[]) {}

  document(): unknown {
    this.skip()
    const first = this.lines[this.i]
    if (!first) return null
    if (first.text === '---') {
      this.i++
      this.skip()
    }
    const line = this.lines[this.i]
    if (!line) return null
    return this.node(line.indent)
  }

  private skip(): void {
    while (this.i < this.lines.length && isBlank(this.lines[this.i])) this.i++
  }

  private peek(): Line | undefined {
    this.skip()
    return this.lines[this.i]
  }

  private node(indent: number): unknown {
    const line = this.peek()
    if (!line || line.indent < indent) return null
    if (isSeqItem(line.text)) return this.seq(line.indent)
    if (KEY.test(line.text)) return this.map(line.indent)
    this.i++
    return this.inline(line.text, line.indent - 1)
  }

  private map(indent: number): Record<string, unknown> {
    const out: Record<string, unknown> = {}
    for (;;) {
      const line = this.peek()
      if (!line || line.indent !== indent || isSeqItem(line.text)) break
      const m = KEY.exec(line.text)
      if (!m) throw new YamlError(`expected "key: value" at "${line.text.slice(0, 60)}"`)
      const key = m[1] !== undefined ? unescapeDouble(m[1]) : m[2] !== undefined ? m[2].replace(/''/g, "'") : (m[3] ?? '').trim()
      const rest = (m[4] ?? '').trim()
      this.i++
      out[key] = this.value(rest, indent)
    }
    return out
  }

  /** The value after `key:` (or `- `), with `indent` the column of its owner. */
  private value(rest: string, indent: number): unknown {
    if (rest === '' || rest.startsWith('#')) {
      const next = this.peek()
      if (!next) return null
      if (next.indent > indent) return this.node(next.indent)
      // A sequence may sit at its key's own indent.
      if (next.indent === indent && isSeqItem(next.text)) return this.seq(indent)
      return null
    }
    if (/^[|>][+-]?\d*$/.test(rest.replace(/\s+#.*$/, ''))) return this.blockScalar(rest, indent)
    return this.inline(rest, indent)
  }

  private seq(indent: number): unknown[] {
    const out: unknown[] = []
    for (;;) {
      const line = this.peek()
      if (!line || line.indent !== indent || !isSeqItem(line.text)) break
      const content = line.text === '-' ? '' : line.text.slice(2).trimStart()
      const offset = line.indent + (line.text.length - content.length)
      if (content === '') {
        this.i++
        out.push(this.value('', indent))
      } else if (isSeqItem(content) || startsAsKey(content)) {
        // `- key: v` (a mapping) or `- - x` (a nested sequence): re-read this line as the
        // first line of that node, at the column its content starts.
        this.lines[this.i] = { indent: offset, text: content }
        out.push(this.node(offset))
      } else {
        this.i++
        out.push(this.inline(content, indent))
      }
    }
    return out
  }

  private blockScalar(header: string, indent: number): string {
    const fold = header.startsWith('>')
    const chomp = header.includes('-') ? 'strip' : header.includes('+') ? 'keep' : 'clip'
    const raw: string[] = []
    let blockIndent = -1
    while (this.i < this.lines.length) {
      const line = this.lines[this.i]
      if (!line) break
      if (line.text === '') {
        raw.push('')
        this.i++
        continue
      }
      if (line.indent <= indent) break
      if (blockIndent < 0) blockIndent = line.indent
      if (line.indent < blockIndent) break
      raw.push(' '.repeat(line.indent - blockIndent) + line.text)
      this.i++
    }
    let text: string
    if (fold) {
      text = raw.reduce((acc, l, k) => {
        if (k === 0) return l
        const prev = raw[k - 1] ?? ''
        if (l === '' || prev === '' || l.startsWith(' ')) return `${acc}\n${l}`
        return `${acc} ${l}`
      }, '')
    } else {
      text = raw.join('\n')
    }
    if (chomp === 'strip') return text.replace(/\n+$/, '')
    if (chomp === 'clip') return text.replace(/\n+$/, '') + '\n'
    return text + '\n'
  }

  /**
   * A scalar or flow collection starting on this line; quoted, flow and plain scalars may
   * continue on following lines indented deeper than `indent`.
   */
  private inline(first: string, indent: number): unknown {
    let text = first
    const continues = () => {
      const next = this.lines[this.i]
      return !!next && next.text !== '' && next.indent > indent && !next.text.startsWith('#')
    }
    if (text.startsWith('"') || text.startsWith("'")) {
      const q = text[0] as '"' | "'"
      while (!closedQuote(text, q) && this.i < this.lines.length) {
        const next = this.lines[this.i]
        this.i++
        text += next && next.text !== '' ? ` ${next.text}` : '\n'
      }
      const end = closingQuoteAt(text, q)
      const body = text.slice(1, end)
      return q === '"' ? unescapeDouble(body) : body.replace(/''/g, "'")
    }
    if (text.startsWith('[') || text.startsWith('{')) {
      while (!balanced(text) && this.i < this.lines.length) {
        const next = this.lines[this.i]
        this.i++
        if (next) text += ` ${next.text}`
      }
      return new Flow(text).value()
    }
    const plain = stripComment(text)
    const parts = [plain]
    while (continues() && !KEY.test(this.lines[this.i]?.text ?? '') && !isSeqItem(this.lines[this.i]?.text ?? '')) {
      parts.push(stripComment(this.lines[this.i]?.text ?? ''))
      this.i++
    }
    return parts.length > 1 ? parts.join(' ') : scalar(plain)
  }
}

/**
 * `- foo: bar` reads as a mapping only when the part before `:` looks like a key, so a
 * filter expression such as `- file.name == "a: b"` stays one string.
 */
function startsAsKey(content: string): boolean {
  const m = KEY.exec(content)
  if (!m) return false
  return m[3] === undefined || !/[()"'=<>!&|]/.test(m[3])
}

function closingQuoteAt(text: string, q: string): number {
  for (let k = 1; k < text.length; k++) {
    const c = text[k]
    if (q === '"' && c === '\\') {
      k++
      continue
    }
    if (c === q) {
      if (q === "'" && text[k + 1] === "'") {
        k++
        continue
      }
      return k
    }
  }
  return -1
}

function closedQuote(text: string, q: string): boolean {
  return closingQuoteAt(text, q) > 0
}

function balanced(text: string): boolean {
  let depth = 0
  let quote: string | undefined
  for (let k = 0; k < text.length; k++) {
    const c = text[k]
    if (quote) {
      if (quote === '"' && c === '\\') k++
      else if (c === quote) quote = undefined
    } else if (c === '"' || c === "'") quote = c
    else if (c === '[' || c === '{') depth++
    else if (c === ']' || c === '}') depth--
  }
  return depth <= 0
}

function stripComment(text: string): string {
  const m = /\s#/.exec(text)
  return (m ? text.slice(0, m.index) : text).trim()
}

function unescapeDouble(s: string): string {
  return s.replace(/\\(u[0-9a-fA-F]{4}|x[0-9a-fA-F]{2}|.)/g, (_, e: string) => {
    if (e[0] === 'u' || e[0] === 'x') return String.fromCharCode(parseInt(e.slice(1), 16))
    return ({ n: '\n', t: '\t', r: '\r', '0': '\0', '"': '"', '\\': '\\', '/': '/', ' ': ' ' } as Record<string, string>)[e] ?? e
  })
}

/** A plain scalar: null, booleans and numbers become values; everything else stays text. */
export function scalar(text: string): unknown {
  const t = text.trim()
  if (t === '' || t === '~' || t === 'null' || t === 'Null' || t === 'NULL') return null
  if (/^(true|True|TRUE)$/.test(t)) return true
  if (/^(false|False|FALSE)$/.test(t)) return false
  if (/^[-+]?(\d+|\d*\.\d+)([eE][-+]?\d+)?$/.test(t)) return Number(t)
  if (/^0x[0-9a-fA-F]+$/.test(t)) return parseInt(t, 16)
  return t
}

class Flow {
  k = 0
  constructor(private s: string) {}

  value(): unknown {
    this.ws()
    const c = this.s[this.k]
    if (c === '[') return this.list()
    if (c === '{') return this.object()
    return this.atom(false)
  }

  private ws(): void {
    while (this.k < this.s.length && /\s/.test(this.s[this.k] ?? '')) this.k++
  }

  private list(): unknown[] {
    const out: unknown[] = []
    this.k++ // [
    for (;;) {
      this.ws()
      if (this.s[this.k] === ']') {
        this.k++
        return out
      }
      if (this.k >= this.s.length) throw new YamlError('unclosed [')
      out.push(this.value())
      this.ws()
      if (this.s[this.k] === ',') this.k++
    }
  }

  private object(): Record<string, unknown> {
    const out: Record<string, unknown> = {}
    this.k++ // {
    for (;;) {
      this.ws()
      if (this.s[this.k] === '}') {
        this.k++
        return out
      }
      if (this.k >= this.s.length) throw new YamlError('unclosed {')
      const key = String(this.atom(true) ?? '')
      this.ws()
      let val: unknown = null
      if (this.s[this.k] === ':') {
        this.k++
        val = this.value()
      }
      out[key] = val
      this.ws()
      if (this.s[this.k] === ',') this.k++
    }
  }

  private atom(isKey: boolean): unknown {
    this.ws()
    const c = this.s[this.k]
    if (c === '"' || c === "'") {
      const rest = this.s.slice(this.k)
      const end = closingQuoteAt(rest, c)
      if (end < 0) throw new YamlError('unclosed quote')
      this.k += end + 1
      const body = rest.slice(1, end)
      return c === '"' ? unescapeDouble(body) : body.replace(/''/g, "'")
    }
    const start = this.k
    while (this.k < this.s.length) {
      const ch = this.s[this.k]
      if (ch === ',' || ch === ']' || ch === '}') break
      if (isKey && ch === ':') break
      if (ch === ':' && /\s/.test(this.s[this.k + 1] ?? ' ')) break
      this.k++
    }
    return scalar(this.s.slice(start, this.k))
  }
}

